void replayPublicDirectoryAndMembers(){QString path=qEnvironmentVariable("SECTOR_WATCH_REPLAY_INPUT");if(path.isEmpty())QSKIP("需已保存的公开源原始证据目录");auto read=[](const QString& file){QFile f(file);if(!f.open(QIODevice::ReadOnly))throw std::runtime_error("缺少重放证据");return f.readAll();};auto receipt=QJsonDocument::fromJson(read(path+"/receipt.json")).object();QVERIFY(receipt["error"].toString().isEmpty());Network net;for(auto v:receipt["requests"].toArray()){auto r=v.toObject();auto bytes=read(path+"/"+r["rawFile"].toString());QCOMPARE(QString::fromLatin1(QCryptographicHash::hash(bytes,QCryptographicHash::Sha256).toHex()),r["sha256"].toString());QCOMPARE(bytes.size(),r["bytes"].toInt());net.replies.append(bytes);}QCOMPARE(net.replies.size(),4);Feed feed(nullptr,&net);QSignalSpy done(&feed,&Feed::finished);QVERIFY(feed.start(query("sina-public-industry","industry")));QTRY_COMPARE(done.size(),1);QVERIFY(done[0][2].toString().isEmpty());auto catalog=QJsonDocument::fromJson(read(path+"/catalog.json")).object();QCOMPARE(done[0][1].toJsonObject()["items"],catalog["items"]);QVERIFY(feed.start(query("sina-public-industry","industry","sw2_480200")));QTRY_COMPARE(done.size(),2);QVERIFY(done[1][2].toString().isEmpty());auto members=QJsonDocument::fromJson(read(path+"/constituents.json")).object();QCOMPARE(done[1][1].toJsonObject()["items"],members["items"]);Store store(path+"/sector-watch-demo.sqlite");QCOMPARE(store.read(catalog["query"].toObject())["snapshot"].toObject(),catalog);QCOMPARE(store.read(members["query"].toObject())["snapshot"].toObject(),members);SectorWatchPage p(path+"/sector-watch-demo.sqlite",false);p.restoreState(QJsonObject{{"provider","sina"},{"taxonomy","industry"},{"boardKey","sina-public-industry|industry|sw2_480200"},{"boardFilter","国有大型银行"}});QSignalSpy observe(&p,&SectorWatchPage::observeInstrument),add(&p,&SectorWatchPage::addWatchlist);p.show();QTRY_COMPARE(p.findChild<QTableWidget*>("sectorBoards")->rowCount(),1);auto table=p.findChild<QTableWidget*>("sectorMembers");QTRY_COMPARE(table->rowCount(),6);table->selectRow(0);QTRY_COMPARE(observe.size(),1);QCOMPARE(add.size(),0);QVERIFY(observe[0][0].toJsonObject()["id"].toString().startsWith("SH:stock:"));QVERIFY(!p.findChild<QPushButton*>("sectorFetchCatalog")->isEnabled());}
void boundedPublicDirectoryAndMembers(){if(qEnvironmentVariable("SECTOR_WATCH_CHAIN_READ")!="1")QSKIP("显式启用的单板块公共源验证");QString path=qEnvironmentVariable("SECTOR_WATCH_CHAIN_OUTPUT");QVERIFY(!path.isEmpty()&&!QFile::exists(path));QVERIFY(QDir().mkpath(path));CapturingNetwork net(path);Feed feed(nullptr,&net);QSignalSpy done(&feed,&Feed::finished);Store store(path+"/sector-watch-demo.sqlite");QJsonObject outcome{{"provider","sina-public-industry"},{"taxonomy","industry"},{"observedAt",QJsonValue::Null},{"productionDatabaseTouched",false}};QVERIFY(feed.start(query("sina-public-industry","industry")));QTRY_COMPARE_WITH_TIMEOUT(done.size(),1,9500);auto catalog=done[0][1].toJsonObject();QString error=done[0][2].toString();if(error.isEmpty()){store.save(catalog);exportNew(catalog,path+"/catalog.json");QJsonObject board;for(auto v:catalog["items"].toArray())if(v.toObject()["code"]=="sw2_480200")board=v.toObject();QVERIFY(!board.isEmpty());outcome["board"]=board;QVERIFY(feed.start(query("sina-public-industry","industry",board["code"].toString())));QTRY_COMPARE_WITH_TIMEOUT(done.size(),2,9500);error=done[1][2].toString();auto members=done[1][1].toJsonObject();if(error.isEmpty()){store.save(members);exportNew(members,path+"/constituents.json");QCOMPARE(store.read(members["query"].toObject())["snapshot"].toObject(),members);outcome["coverageComplete"]=members["coverageComplete"];outcome["quoteComplete"]=members["quoteComplete"];outcome["declaredTotal"]=members["declaredTotal"];outcome["startedAt"]=members["startedAt"];outcome["fetchedAt"]=members["fetchedAt"];outcome["sourceTiming"]=members["sourceTiming"];qInfo()<<"PUBLIC_CHAIN_COMPLETE rows="<<members["items"].toArray().size();}else{outcome["coverageComplete"]=false;store.recordFailure(query("sina-public-industry","industry",board["code"].toString()),error.left(1000),QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs));if(!members.isEmpty())exportNew(members,path+"/partial-attempt.json");}}outcome["error"]=error;outcome["requests"]=net.receipts;writeNew(path+"/receipt.json",QJsonDocument(outcome).toJson(QJsonDocument::Indented));QVERIFY(net.saved);if(!error.isEmpty())qInfo().noquote()<<"PUBLIC_CHAIN_UNAVAILABLE:"<<error;}
